const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = [
  { id: 'js', title: '자바스크립트 입문', level: '입문', hours: 12, badge: '신규' },
  { id: 'react', title: '리액트 시작하기', level: '보통', hours: 20, badge: '인기' },
  { id: 'css', title: 'CSS 레이아웃 마스터', level: '보통', hours: 8 },
];

const Badge = ({ label }) => <span className="badge">{label}</span>;

const Course = ({ title, level, hours, badge }) => (
  <article className={badge ? 'course course--sale' : 'course'}>
    <div className="course__head">
      <h3 className="course__title">{title}</h3>
      {badge ? <Badge label={badge} /> : null}
    </div>
    <p className="course__meta">{level} · {hours}시간</p>
  </article>
);

const Section = ({ title, count, children }) => (
  <section className="section">
    <div className="section__head">
      <h2 className="section__title">{title}</h2>
      <span className="section__count">코스 {count}개</span>
    </div>
    {children}
  </section>
);

const Grid = ({ list }) => null; // ← 여기를 채우세요

root.render(
  <Section title="추천 코스" count={courses.length}>
    <Grid list={courses} />
  </Section>
);

